<?php require '../../../config/bootstrap.php';rate_limit('iot_commands',120,60);$key=$_SERVER['HTTP_X_DEVICE_KEY']??'';$code=trim((string)($_GET['device_code']??''));if(!$key||!$code)json_response(['error'=>'Credenciais ausentes'],401);$hash=hash_hmac('sha256',$key,envv('DEVICE_KEY_PEPPER','change-me'));$s=db()->prepare('SELECT d.*,c.secret_hash FROM devices d JOIN device_credentials c ON c.device_id=d.id AND c.active=1 WHERE d.device_code=? LIMIT 1');$s->execute([$code]);$dev=$s->fetch();if(!$dev||!hash_equals($dev['secret_hash'],$hash))json_response(['error'=>'Não autorizado'],401);$p=db();$p->prepare('UPDATE device_commands SET status="expired" WHERE device_id=? AND status="queued" AND expires_at<NOW()')->execute([$dev['id']]);$s=$p->prepare('SELECT * FROM device_commands WHERE device_id=? AND status="queued" AND expires_at>=NOW() ORDER BY id LIMIT 1');$s->execute([$dev['id']]);$cmd=$s->fetch();if(!$cmd)json_response(['command'=>null]);$p->prepare('UPDATE device_commands SET status="sent",sent_at=NOW() WHERE id=? AND status="queued"')->execute([$cmd['id']]);json_response(['command'=>['id'=>(int)$cmd['id'],'type'=>$cmd['command_type'],'payload'=>json_decode($cmd['payload'],true),'expires_at'=>$cmd['expires_at']]]);
